package com.fuelflex.platform.operations.service;
import org.springframework.stereotype.Service; import com.fuelflex.platform.notification.dto.request.CreateNotificationCommand; import com.fuelflex.platform.notification.entity.NotificationCategory; import com.fuelflex.platform.notification.service.NotificationService; import com.fuelflex.platform.station.entity.Station; import com.fuelflex.platform.station.service.StationAccessService; import com.fuelflex.platform.user.entity.User; import com.fuelflex.platform.user.repository.UserRepository; import lombok.RequiredArgsConstructor;
@Service @RequiredArgsConstructor public class SupervisorOperationalNotifier{private final UserRepository users;private final StationAccessService access;private final NotificationService notifications;
 public void inform(User actor,Station station,String event,String resourceType,java.util.UUID resourceId){for(User recipient:users.findEnabledByOrganizationIdAndRoleCode(actor.getOrganization().getId(),"SUPERVISOR")){if(!access.canAccessStation(recipient,station.getId()))continue;notifications.create(CreateNotificationCommand.builder().recipientId(recipient.getId()).organizationId(actor.getOrganization().getId()).stationId(station.getId()).actorId(actor.getId()).eventType(event).category(NotificationCategory.INFORMATION).titleKey("notifications:events."+event+".title").messageKey("notifications:events."+event+".message").resourceType(resourceType).resourceId(resourceId).requiresAction(false).build());}}
}
